package com.muthumol.player.dummy;
import android.view.*;import android.media.AudioManager;import android.content.Context;import android.graphics.Rect;import android.widget.*;
/** Touch gestures only on the video surface, leaving controls and TV remote alone. */
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
final class PlayerGestures {
 final PlayerActivity a;final GestureDetector detector;float x,y,brightness;int volume;boolean eligible,sliding;
 PlayerGestures(PlayerActivity a){this.a=a;detector=new GestureDetector(a,new GestureDetector.SimpleOnGestureListener(){@Override public boolean onDown(MotionEvent e){return true;}@Override public boolean onDoubleTap(MotionEvent e){if(!eligible||sliding||a.player==null)return false;long delta=e.getX()<a.view.getWidth()/2f?-10000:10000;long duration=a.player.getDuration();long target=Math.max(0,a.player.getCurrentPosition()+delta);if(duration>0)target=Math.min(duration,target);a.player.seekTo(target);feedback(delta>0?"+10 seconds":"−10 seconds");return true;}});}
 static boolean vertical(float dx,float dy,float threshold){return Math.abs(dy)>threshold&&Math.abs(dy)>Math.abs(dx)*1.5f;}
 boolean touch(MotionEvent e){if(a.player==null||e.getToolType(0)!=MotionEvent.TOOL_TYPE_FINGER||a.tvTools!=null&&a.tvTools.locked)return false;int action=e.getActionMasked();if(action==MotionEvent.ACTION_DOWN){x=e.getX();y=e.getY();sliding=false;eligible=e.getPointerCount()==1&&!interactive(a.getWindow().getDecorView(),(int)e.getRawX(),(int)e.getRawY());AudioManager am=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);volume=am.getStreamVolume(AudioManager.STREAM_MUSIC);brightness=a.getWindow().getAttributes().screenBrightness;if(brightness<0)try{brightness=android.provider.Settings.System.getInt(a.getContentResolver(),android.provider.Settings.System.SCREEN_BRIGHTNESS)/255f;}catch(Exception ignored){brightness=.5f;}}
 if(e.getPointerCount()>1)eligible=false;
 if(eligible&&action==MotionEvent.ACTION_MOVE){float dy=y-e.getY(),dx=x-e.getX();if(!sliding&&vertical(dx,dy,Ui.dp(a,24)))sliding=true;if(sliding){float change=dy/Math.max(1,a.view.getHeight()*.7f);if(x>=a.view.getWidth()/2f){AudioManager am=(AudioManager)a.getSystemService(Context.AUDIO_SERVICE);int max=am.getStreamMaxVolume(AudioManager.STREAM_MUSIC),v=Math.max(0,Math.min(max,volume+Math.round(change*max)));am.setStreamVolume(AudioManager.STREAM_MUSIC,v,0);feedback("Volume "+Math.round(v*100f/Math.max(1,max))+"%");}else{WindowManager.LayoutParams params=a.getWindow().getAttributes();params.screenBrightness=Math.max(.02f,Math.min(1,brightness+change));a.getWindow().setAttributes(params);feedback("Brightness "+Math.round(params.screenBrightness*100)+"%");}return true;}}
 boolean doubleTap=eligible&&!sliding&&detector.onTouchEvent(e);boolean consume=sliding||doubleTap;if(action==MotionEvent.ACTION_CANCEL)eligible=false;return consume;}
 boolean interactive(View v,int x,int y){if(v.getVisibility()!=View.VISIBLE)return false;Rect r=new Rect();if(!v.getGlobalVisibleRect(r)||!r.contains(x,y))return false;if(v instanceof Button||v instanceof ImageButton||v instanceof SeekBar||v instanceof androidx.media3.ui.DefaultTimeBar)return true;if(v instanceof ViewGroup){ViewGroup group=(ViewGroup)v;for(int i=group.getChildCount()-1;i>=0;i--)if(interactive(group.getChildAt(i),x,y))return true;}return false;}
 void feedback(String text){if(a.seekFeedback!=null){a.seekFeedback.setText(text);a.seekFeedback.setVisibility(View.VISIBLE);a.ui.removeCallbacks(a.hideSeekFeedback);a.ui.postDelayed(a.hideSeekFeedback,1000);}}
}
